head.script:
scwin.screenId = "jlddst36600";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.ThisTabBind();
        $('section.contents nav.tabgroup li').eq(0).children("a").trigger("click");
        $(document).find('div[id=dialog-loading]').css("display", "none");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst36600.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst36600.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.ThisTabBind
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.ThisTabBind = function () {
    /* sdd-asis-lifecycle:begin ThisTabBind — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const btns = $('section.contents nav.tabgroup li');
    btns.each(function(i) {
            $(this).data("idx", i);
    });
    btns.each(function(i) {
            const a = $(this).children("a");
            a.bind("click focus", function() {
                    $(this).parent().parent().children("li").removeClass("active");
                    $(this).parent().addClass("active");
                    const idx = $(this).parent().data("idx");
                    $('article.pcontents div.tabBlock div.block-ctt').addClass("hide");
                    $('article.pcontents div.tabBlock div.block-ctt').eq(idx).removeClass("hide");
            });
    });
    /* sdd-asis-lifecycle:end */
};
